SELECT
  cast(sum(population) as integer) AS population
FROM full_2020
WHERE month = '2019-06'
  AND country = 'SAU'
  AND type = 'total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((49.5887912 27.3376038,50.1254263 26.6879303,50.224378 26.4039523,50.2180194 26.190184,50.1480755 26.0417405,50.2717809 25.6272433,50.0633798 25.772388,49.6491257 25.626168,49.6887041 25.4345037,49.7836923 25.3784944,49.5923966 25.2759419,49.4116552 25.2771349,48.991678 26.1229596,49.062335 26.9414257,49.2185242 27.3220259,49.5643717 27.3550602,49.5887912 27.3376038))')
  );
